import unittest
import pytest
from candidate import truncate_number


class TestTruncateNumber(unittest.TestCase):
    def test_truncate_number_basic_decimal(self):
        self.assertAlmostEqual(truncate_number(3.5), 0.5)

    def test_truncate_number_quarter(self):
        self.assertAlmostEqual(truncate_number(1.25), 0.25)

    def test_truncate_number_seven_eighths(self):
        self.assertAlmostEqual(truncate_number(2.875), 0.875)

    def test_truncate_number_half(self):
        self.assertAlmostEqual(truncate_number(0.5), 0.5)

    def test_truncate_number_integer_value_returns_zero(self):
        self.assertAlmostEqual(truncate_number(5.0), 0.0)

    def test_truncate_number_one_returns_zero(self):
        self.assertAlmostEqual(truncate_number(1.0), 0.0)

    def test_truncate_number_zero_returns_zero(self):
        self.assertAlmostEqual(truncate_number(0.0), 0.0)

    def test_truncate_number_large_number(self):
        self.assertAlmostEqual(truncate_number(1000000.25), 0.25)

    def test_truncate_number_small_decimal(self):
        self.assertAlmostEqual(truncate_number(0.001), 0.001)

    def test_truncate_number_very_close_to_integer(self):
        self.assertAlmostEqual(truncate_number(3.0000001), 0.0000001, places=7)

    def test_truncate_number_close_to_next_integer(self):
        self.assertAlmostEqual(truncate_number(3.999999), 0.999999, places=6)

    def test_truncate_number_negative_number(self):
        self.assertAlmostEqual(truncate_number(-3.5), 0.5)

    def test_truncate_number_negative_integer(self):
        self.assertAlmostEqual(truncate_number(-5.0), 0.0)

    def test_truncate_number_negative_small(self):
        self.assertAlmostEqual(truncate_number(-0.5), 0.5)

    def test_truncate_number_integer_input(self):
        self.assertAlmostEqual(truncate_number(7), 0.0)

    def test_truncate_number_integer_input_nonzero(self):
        self.assertAlmostEqual(truncate_number(4), 0.0)

    def test_truncate_number_returns_float_type(self):
        self.assertIsInstance(truncate_number(3.5), float)

    def test_truncate_number_returns_float_for_integer_input(self):
        self.assertIsInstance(truncate_number(7), float)

    def test_truncate_number_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            truncate_number(None)

    def test_truncate_number_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            truncate_number("3.5")

    def test_truncate_number_missing_argument_raises_type_error(self):
        with self.assertRaises(TypeError):
            truncate_number()

    def test_truncate_number_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            truncate_number([3.5])

    def test_truncate_number_dict_raises_type_error(self):
        with self.assertRaises(TypeError):
            truncate_number({"a": 1})

    def test_truncate_number_result_less_than_one(self):
        self.assertLess(truncate_number(999.99), 1.0)

    def test_truncate_number_result_non_negative(self):
        self.assertGreaterEqual(truncate_number(3.5), 0.0)

    def test_truncate_number_repeated_calls_consistent(self):
        result1 = truncate_number(4.75)
        result2 = truncate_number(4.75)
        self.assertEqual(result1, result2)

    def test_truncate_number_multiple_values_consistency(self):
        self.assertAlmostEqual(truncate_number(1.1), 0.1)
        self.assertAlmostEqual(truncate_number(2.2), 0.2)
        self.assertAlmostEqual(truncate_number(3.3), 0.3)
        self.assertAlmostEqual(truncate_number(4.4), 0.4)
        self.assertAlmostEqual(truncate_number(5.5), 0.5)


if __name__ == '__main__':
    unittest.main()
